import numpy as np
Wx = W['W_x'].reshape(-1); Wh=W['W_h']; Wo=W['W_o']
print("Wx", Wx)
c = 1.0/Wx          # makes GAIN all ones
print("c", c)
M = (Wh * c[:,None] / c[None,:]).T   # M[v][u] = c_u*Wh[v,u]/c_v
R = Wo * c[:,None]
print("M range", np.abs(M).max(), np.abs(M).min())
print("R range", np.abs(R).max(), np.abs(R).min())

def fwd(x, M, R, gain=None, nd=None):
    B=x.shape[0]
    if nd is not None:
        M=np.round(M,nd); R=np.round(R,nd)
        if gain is not None: gain=np.round(gain,nd)
    s=np.zeros((B,8))
    if gain is None: gain=np.ones(8)
    for t in range(8):
        acc = x[:,t:t+1]*gain[None,:] + s@M
        s = np.maximum(acc,0.0)
    return s@R

def agree(out, ref):
    return (out.argmax(1)==ref.argmax(1)).mean()

ref = run(X)
for nd in [None, 8, 7, 6]:
    o = fwd(X, M, R, None, nd)
    print(nd, "acc %.4f"%(agree(o,ref)), "R2 %.6f"%(1-((o-ref)**2).sum()/((ref-ref.mean(0))**2).sum()))

def build(c):
    K = Wh * c[None,:] / c[:,None]
    return c*Wx, K, Wo / c[:,None]

def rep2(c, nd=None):
    gain,K,R = build(np.asarray(c,float))
    if nd is not None: gain,K,R=np.round(gain,nd),np.round(K,nd),np.round(R,nd)
    s=np.zeros((X.shape[0],8))
    for t in range(8):
        s=np.maximum(X[:,t:t+1]*gain[None,:] + s@K,0.0)
    o=s@R
    r2=1-((o-ref)**2).sum()/((ref-ref.mean(0))**2).sum()
    return round((o.argmax(1)==ref.argmax(1)).mean(),4), round(r2,6)

